            ordered=sorted(v)
            for ix,key in enumerate(ordered):
                val=v[key]
                if isinstance(val,(dict,list)):
                    rendered=render(val,level+1)
                    if ix<len(ordered)-1: rendered+=','
                    out.append(indent+str(key)+':')
                    out.extend(rendered.splitlines())
                else:
                    rendered=typ(val) if keys else render(val,level+1)
                    suffix=',' if keys and ix<len(ordered)-1 else ''
                    out.append(indent+str(key)+': '+rendered+suffix)
            out.append(pad+'}')
            return '\n'.join(out)
        if isinstance(v,list):
