"""Compact word/line/byte counter."""
import os
import sys


def _counts(data: bytes):
    # wc counts newline characters; whitespace-delimited words; raw bytes.
    return data.count(b"\n"), len(data.split()), len(data), len(data.decode("utf-8", errors="replace"))


def format_wc(args, stdin=None):
    flags = []
    aliases = {"--lines": "l", "--words": "w", "--bytes": "c", "--chars": "m"}
    for arg in args:
        if arg in aliases:
            flags.append(aliases[arg])
        elif arg.startswith("-") and not arg.startswith("--"):
            flags.extend(ch for ch in arg[1:] if ch in "lwcm")
    flags = [ch for ch in "lwmc" if ch in flags]
    paths = [a for a in args if not a.startswith("-") and a not in aliases]
    if "--" in args:
        paths = args[args.index("--") + 1:]
    use_stdin = not paths
    rows = []
    for path in paths:
        try:
            with open(path, "rb") as f:
                rows.append((path, _counts(f.read())))
        except OSError:
            continue
    if use_stdin:
        data = sys.stdin.buffer.read() if stdin is None else stdin
        if isinstance(data, str):
            data = data.encode()
        rows = [(None, _counts(data))]
    if not rows:
        return ""
    def selected(c):
        l, w, b, chars = c
        if not flags:
            return f"{l}L {w}W {b}B"
        values = []
        for flag in flags:
            values.append(str(b if flag == "c" else chars if flag == "m" else l if flag == "l" else w))
        return " ".join(values)
    if len(rows) == 1 and (use_stdin or len(flags) == 1):
        return selected(rows[0][1]) + "\n"
    if len(rows) == 1:
        return selected(rows[0][1]) + "\n"
    output=[]
    total=[0,0,0,0]
    for path,c in rows:
        for i,n in enumerate(c): total[i]+=n
        output.append(selected(c) + " " + os.path.basename(path))
    output.append("Σ " + selected(total))
    return "\n".join(output)+"\n"


def run_wc(args, stdin=None):
    sys.stdout.write(format_wc(args, stdin))
    paths = [a for a in args if not a.startswith("-")]
    if "--" in args:
