SENSITIVE=re.compile(r'(SECRET|TOKEN|PASSWORD|PASSWD|KEY|CREDENTIAL|AUTH)',re.I)
RUNTIME=('CARGO_HOME','GOMODCACHE','RUSTUP_HOME')
TOOLS=('COLORTERM','GIT_MERGE_AUTOEDIT','GIT_PAGER','GIT_TERMINAL_PROMPT','SHELL','TERM')
