def env_output(args):
    if '-h' in args or '--help' in args:
        return ('Show environment variables (filtered, sensitive masked)\n\nUsage: executable env [OPTIONS]\n\nOptions:\n  -f, --filter <FILTER>  Filter by name (e.g. PATH, AWS)\n      --show-all         Show all (include sensitive)\n  -v, --verbose...       Verbosity level (-v, -vv, -vvv)\n      --ultra-compact    Ultra-compact mode: ASCII icons, inline format (Level 2 optimizations)\n      --skip-env         Set SKIP_ENV_VALIDATION=1 for child processes (Next.js, tsc, lint, prisma)\n  -h, --help             Print help\n')
    filt=None;show=False;i=0
    while i<len(args):
        a=args[i]
        if a in ('-f','--filter') and i+1<len(args):filt=args[i+1];i+=1
        elif a.startswith('--filter='):filt=a.split('=',1)[1]
        elif a=='--show-all':show=True
        i+=1
    env=os.environ
    def allowed(k):return filt is None or filt.lower() in k.lower()
    lines=[]
    if filt is not None and not allowed('PATH'):
        lines.append('')
    if allowed('PATH') and 'PATH' in env:
        raw_path=env['PATH']
        paths=raw_path.split(os.pathsep)
        compressed=False
        if len(raw_path)>120 and len(paths)>2:
            paths=[paths[0],os.pathsep.join(paths[1:])]
            compressed=True
        lines.extend(['PATH Variables:',f'  PATH ({len(paths)} entries):'])
        for p in paths[:10]:
            v=(p[:3]+'... ('+str(len(raw_path))+' chars)' if compressed and p==paths[1]
               else p if len(p)<=60 else p[:4]+'... ('+str(len(p))+' chars)')
            lines.append('    '+v)
        if len(paths)>10: lines.append(f'    ... +{len(paths)-10} more')
        lines.append('')
    known=set(RUNTIME+TOOLS+OTHER+('PATH',))
    groups=(('Language/Runtime',RUNTIME),('Tools',TOOLS),('Other',OTHER))
    for title,names in groups:
        entries=[k for k in names if k in env and allowed(k)]
        if title=='Other' and filt is not None:
            entries.extend(k for k in sorted(env) if k not in known and allowed(k))
        if title=='Other' and filt is not None: entries=sorted(set(entries))
        if not entries:continue
        lines.append(title+':')
        for k in entries:
            val=env[k]
            if not show and SENSITIVE.search(k):val=(val[:2]+'****'+val[-2:] if len(val)>=5 else '****')
            lines.append(f'  {k}={val}')
        lines.append('')
    if filt is None:
        lines.append(f'Total: {len(env)} vars (showing 16 relevant)')
    return '\n'.join(lines).rstrip()+'\n' if lines else ''

